mapper.select:
SELECT o.outbound_id, o.outbound_date, o.coa_code, o.outbound_location, o.remark, o.created_at, COALESCE(s.total_qty, 0) AS total_qty, COALESCE(s.item_count, 0) AS item_count FROM outbound o LEFT JOIN ( SELECT outbound_id, SUM(quantity) AS total_qty, COUNT(*) AS item_count FROM outbound_item GROUP BY outbound_id ) s ON s.outbound_id = o.outbound_id
AND o.outbound_date BETWEEN #{startDate} AND #{endDate}
ORDER BY o.outbound_date DESC, o.outbound_id DESC

SELECT outbound_id, outbound_date, coa_code, outbound_location, remark, created_at
  FROM outbound
 WHERE outbound_id = #{outboundId}
